package cli

import (
	"bytes"
	"context"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"net/http"
	"net/url"
	"os"
	"strings"
	"time"
)

// Webhooks: telling something else that a brain changed.
//
// Everything a brain learns stays inside it until a person runs a command. That
// is fine for a tool you sit in front of and useless for anything downstream —
// a CI check that wants to know a new invariant was recorded, a Slack channel
// that should see a decision, an index that needs rebuilding. mem0 ships eight
// event types; we shipped none, and the gap note called it packaging rather
// than design, which is exactly right.
//
// It is also egress from a product whose SECURITY.md says the default build
// makes no network calls. So the rules are strict and they are not negotiable
// by configuration:
//
//   - Off unless ENTIRE_BRAIN_WEBHOOK_URL is set. No file, no discovery, no
//     implicit endpoint. Something has to be typed.
//   - The existing egress gate wins. ENTIRE_BRAIN_NO_EGRESS or LOCAL_ONLY
//     silences webhooks even when a URL is configured, and that check is made
//     here rather than trusted to the caller. A local-only promise that one
//     subsystem can opt out of is not a promise.
//   - Fact TEXT is never sent. The payload carries ids, kinds, taxonomy paths
//     and counts — enough to trigger work, not enough to leak what the brain
//     knows to whatever is on the other end of a URL. A webhook is a
//     notification, not a replication channel.
//   - Delivery never fails a command. Recording a fact succeeds or fails on its
//     own terms; a webhook that times out is reported to stderr and dropped.
//     The alternative is a brain that cannot record anything because something
//     unrelated is down.

const (
	webhookURLEnv    = "ENTIRE_BRAIN_WEBHOOK_URL"
	webhookSecretEnv = "ENTIRE_BRAIN_WEBHOOK_SECRET"
	webhookTimeout   = 5 * time.Second
)

// Event names. Small and specific: a consumer should be able to switch on these
// without parsing a payload to find out what happened.
const (
	WebhookFactRecorded   = "fact.recorded"
	WebhookFactRetracted  = "fact.retracted"
	WebhookFactSuperseded = "fact.superseded"
	WebhookFactsImported  = "facts.imported"
	WebhookIndexRefreshed = "index.refreshed"
)

// webhookEvent is the whole payload. Note what is absent: no fact text, no
// source excerpts, no transcript content.
type webhookEvent struct {
	Event     string         `json:"event"`
	Timestamp string         `json:"timestamp"`
	Repo      string         `json:"repo,omitempty"`
	Branch    string         `json:"branch,omitempty"`
	FactID    string         `json:"fact_id,omitempty"`
	Kind      string         `json:"kind,omitempty"`
	Paths     []string       `json:"paths,omitempty"`
	Counts    map[string]int `json:"counts,omitempty"`
}

// webhookEnabled reports whether a webhook should be sent, and why not when it
// should not. The egress gate is checked first and deliberately: a configured
// URL must not be able to override a local-only declaration.
func webhookEnabled() (endpoint string, ok bool, reason string) {
	if securityToggleEnabled("ENTIRE_BRAIN_NO_EGRESS") || securityToggleEnabled("ENTIRE_BRAIN_LOCAL_ONLY") {
		return "", false, "egress is disabled by ENTIRE_BRAIN_NO_EGRESS/LOCAL_ONLY"
	}
	raw := strings.TrimSpace(os.Getenv(webhookURLEnv))
	if raw == "" {
		return "", false, "no " + webhookURLEnv + " configured"
	}
	parsed, err := url.Parse(raw)
	if err != nil || parsed.Scheme == "" || parsed.Host == "" {
		return "", false, fmt.Sprintf("%s is not a valid absolute URL", webhookURLEnv)
	}
	if parsed.Scheme != "http" && parsed.Scheme != "https" {
		// A file:// or unix:// "webhook" is not a webhook, and letting one
		// through turns an env var into an arbitrary-write primitive.
		return "", false, fmt.Sprintf("%s must be http or https, got %q", webhookURLEnv, parsed.Scheme)
	}
	return raw, true, ""
}

// signWebhook returns the hex HMAC-SHA256 of the body under the configured
// secret, or "" when none is set. Without it a receiver cannot distinguish a
// notification from this brain from a POST by anything else that learned the
// URL.
func signWebhook(body []byte) string {
	secret := strings.TrimSpace(os.Getenv(webhookSecretEnv))
	if secret == "" {
		return ""
	}
	mac := hmac.New(sha256.New, []byte(secret))
	mac.Write(body)
	return hex.EncodeToString(mac.Sum(nil))
}

// emitWebhook delivers one event. It returns an error only so tests can assert
// on it; callers deliberately ignore it, because a brain must not fail to
// record a fact because something downstream is unreachable.
func emitWebhook(ctx context.Context, event webhookEvent) error {
	endpoint, ok, reason := webhookEnabled()
	if !ok {
		// Not an error: "no webhook configured" is the normal case.
		_ = reason
		return nil
	}
	if strings.TrimSpace(event.Timestamp) == "" {
		event.Timestamp = time.Now().UTC().Format(time.RFC3339)
	}
	body, err := json.Marshal(event)
	if err != nil {
		return fmt.Errorf("encode webhook: %w", err)
	}
	if ctx == nil {
		ctx = context.Background()
	}
	ctx, cancel := context.WithTimeout(ctx, webhookTimeout)
	defer cancel()

	request, err := http.NewRequestWithContext(ctx, http.MethodPost, endpoint, bytes.NewReader(body))
	if err != nil {
		return fmt.Errorf("build webhook request: %w", err)
	}
	request.Header.Set("Content-Type", "application/json")
	request.Header.Set("User-Agent", "entire-brain")
	request.Header.Set("X-Entire-Event", event.Event)
	if signature := signWebhook(body); signature != "" {
		request.Header.Set("X-Entire-Signature-256", "sha256="+signature)
	}

	response, err := http.DefaultClient.Do(request)
	if err != nil {
		return fmt.Errorf("deliver webhook: %w", err)
	}
	defer response.Body.Close()
	if response.StatusCode >= 400 {
		return fmt.Errorf("webhook endpoint returned %d", response.StatusCode)
	}
	return nil
}

// notifyWebhook is what callers use: fire and forget, with a warning on stderr
// so a silently broken endpoint is still discoverable.
func notifyWebhook(ctx context.Context, event webhookEvent) {
	if err := emitWebhook(ctx, event); err != nil {
		fmt.Fprintf(os.Stderr, "warning: webhook %s not delivered: %v\n", event.Event, err)
	}
}

