	dir := t.TempDir()
	good := factRecord{ID: "fact:aaaa1111", Paths: []string{"architecture.api.ports"}, Text: "Ports start at 8000.", Status: factStatusActive}
	// Two facts colliding on one filename: the first is written, then the
