// Locus drift asks whether a fact's code locus still exists in THIS worktree.
// A global fact was never scoped to this repository, so any path it mentions
// would be reported stale in every repository except the one it was written in
// — and the fact would be flagged VerificationRequired on every surface.
// recall already excluded them; query/search/vsearch and brief did not.
func TestGlobalFactsAreExemptFromLocusDrift(t *testing.T) {
	global := factRecord{
		ID:     "global-1",
		Text:   "Migrations live in db/migrations/0001_init.sql",
		Paths:  normalizeFactPaths([]string{"db/migrations/0001_init.sql"}),
		Status: factStatusActive,
	}
	repoDir := t.TempDir() // the path above does not exist here, so drift would fire

	if drift := factLocusDrift(repoDir, global); len(drift) == 0 {
		t.Skip("fixture no longer produces drift, so this test would pass vacuously")
	}

	withoutExemption := annotateFactLocusTrust(repoDir, global, unifiedResult{Source: "fact", ID: global.ID}, nil)
	if !withoutExemption.VerificationRequired {
		t.Fatal("the fixture must be one that drift actually flags")
	}

	got := annotateFactLocusTrust(repoDir, global, unifiedResult{Source: "fact", ID: global.ID},
		map[string]bool{global.ID: true})
	if got.VerificationRequired {
		t.Fatalf("a global fact was flagged for drift in a repo it was never scoped to: %+v", got.Caveats)
	}
	if !got.Global {
		t.Fatal("a global fact reached a caller unlabelled; a universal convention must not read as this repo's own")
	}
}

func TestRepositoryFactsStillGetLocusDrift(t *testing.T) {
	// The exemption must not turn into "never check drift".
	local := factRecord{
		ID:     "local-1",
		Text:   "Migrations live in db/migrations/0001_init.sql",
		Paths:  normalizeFactPaths([]string{"db/migrations/0001_init.sql"}),
		Status: factStatusActive,
	}
	repoDir := t.TempDir()
	if drift := factLocusDrift(repoDir, local); len(drift) == 0 {
		t.Skip("fixture no longer produces drift")
	}
	got := annotateFactLocusTrust(repoDir, local, unifiedResult{Source: "fact", ID: local.ID},
		map[string]bool{"some-other-global": true})
	if !got.VerificationRequired {
		t.Fatal("a repository fact stopped being flagged for stale locus")
	}
	if got.Global {
		t.Fatal("a repository fact was labelled global")
	}
}
EOF
