// tokenDocumentFrequencies counts, for each token, how many symbols contain it.
//
// One pass rather than one per token. symbol_fts has no index — every match is
// instr() over every row — so asking separately for each token walked the whole
// corpus once per token, and a five-word query paid for five walks of a table
// that had not changed between them. Measured on a 50k-symbol store, that was
// 77-84% of the time a multi-word query spent in SQLite.
//
// The counts are identical to the per-token form: same instr(), same rows, just
// accumulated in a single scan. Document frequency feeds IDF weighting, so an
// approximation here would silently re-rank results.
func tokenDocumentFrequencies(db *sql.DB, tokens []string) ([]int, error) {
	if len(tokens) == 0 {
		return nil, nil
	}
	columns := make([]string, len(tokens))
	args := make([]any, len(tokens))
