// tokenDocumentFrequencies counts, for each token, how many symbols contain it,
// in one pass rather than one per token. symbol_fts has no index, so each
// separate count walked the whole corpus, and a five-word query paid for five
// walks of a table that had not changed between them. The counts are identical
// to the per-token form: same instr(), same rows, accumulated in a single scan.
func tokenDocumentFrequencies(db *sql.DB, tokens []string) ([]int, error) {
	if len(tokens) == 0 {
		return nil, nil
	}
	columns := make([]string, len(tokens))
	args := make([]any, len(tokens))
	for i, token := range tokens {
		columns[i] = "SUM(CASE WHEN instr(lower(text), ?) > 0 THEN 1 ELSE 0 END)"
