	}
	counts := make([]int, len(tokens))
	dest := make([]any, len(tokens))
	for i := range counts {
		dest[i] = &counts[i]
	}
	query := `SELECT ` + strings.Join(columns, ", ") + ` FROM symbol_fts`
	if err := db.QueryRow(query, args...).Scan(dest...); err != nil {
		return nil, err
	}
	return counts, nil
}
