			if err != nil {
				return nil, fmt.Errorf("%s: %w", name, err)
			}
			result[name] = content
		}
		return result, nil
	}
	before, err := snapshot()
	if err != nil {
		return nil, err
	}
	if err := Install(root, render, io.Discard); err != nil {
		return nil, err
	}
	after, err := snapshot()
	if err != nil {
		return nil, err
	}
	changed := []string{}
