	}
}

// Unparseable or unexpected content is reported, never overwritten.
func TestPreEditHookMergeRefusesRatherThanOverwrite(t *testing.T) {
	t.Parallel()
	for name, body := range map[string]string{
		"invalid json":      `{"hooks": `,
		"hooks not object":  `{"hooks": "nope"}`,
	} {
