// The first wiring of the pre-edit hook passed `--file "$CLAUDE_FILE_PATH"`.
// No such variable exists: measured against Claude Code 2.1.288, a PreToolUse
// hook receives its payload as JSON on stdin and the CLAUDE_* environment holds
// CLAUDE_PROJECT_DIR, CLAUDE_PID, CLAUDE_EFFORT, CLAUDE_TRANSCRIPT_PATH and
// CLAUDE_CODE_ENTRYPOINT -- and nothing naming the edited file. The flag
// expanded to "" on every edit, so the hook errored every time and served
// nothing. It was installed and inert, which is the worst of both.
func TestHookReadsTheFilePathFromTheHarnessPayload(t *testing.T) {
	t.Parallel()

	// The exact shape captured from Claude Code 2.1.288.
	const real = `{"session_id":"20373dcb","transcript_path":"/x/y.jsonl",
	  "cwd":"/repo","permission_mode":"bypassPermissions",
	  "hook_event_name":"PreToolUse","tool_name":"Write",
	  "tool_input":{"file_path":"/repo/internal/cli/semantic.go","content":"x"},
	  "tool_use_id":"toolu_01"}`

	if got := hookFileFromStdin(strings.NewReader(real)); got != "/repo/internal/cli/semantic.go" {
		t.Fatalf("file path from the real payload = %q, want the tool_input.file_path", got)
	}
}

// NotebookEdit names its target notebook_path, not file_path. The installed
// matcher includes NotebookEdit, so ignoring it would leave that tool wired to
// a hook that can never resolve a path.
func TestHookReadsNotebookPathToo(t *testing.T) {
	t.Parallel()

	const nb = `{"hook_event_name":"PreToolUse","tool_name":"NotebookEdit",
	  "tool_input":{"notebook_path":"/repo/analysis.ipynb"}}`

	if got := hookFileFromStdin(strings.NewReader(nb)); got != "/repo/analysis.ipynb" {
		t.Fatalf("notebook path = %q, want tool_input.notebook_path", got)
	}
}

// Every malformed input is silence, never an error. A hook that fails breaks
// the harness it is wired into, and an edit must never be blocked because the
// brain could not parse something.
func TestHookPayloadFailuresAreSilent(t *testing.T) {
	t.Parallel()

	for name, in := range map[string]string{
		"empty":            "",
		"not json":         "this is not json at all",
		"json but no tool": `{"hook_event_name":"PreToolUse"}`,
		"empty file_path":  `{"tool_input":{"file_path":"   "}}`,
		"wrong types":      `{"tool_input":{"file_path":123}}`,
		"truncated":        `{"tool_input":{"file_path":"/a/b.go"`,
	} {
		t.Run(name, func(t *testing.T) {
			if got := hookFileFromStdin(strings.NewReader(in)); got != "" {
				t.Fatalf("want silence for %s, got %q", name, got)
			}
		})
	}
	if got := hookFileFromStdin(nil); got != "" {
		t.Fatalf("a nil reader must be silence, got %q", got)
	}
}

// The wiring must not pass a variable the harness does not define. A path that
// expands to "" is indistinguishable from a working hook until someone checks
// whether a fact was ever served.
func TestInstalledWiringDoesNotReferenceANonexistentVariable(t *testing.T) {
	t.Parallel()

	root := t.TempDir()
	if _, err := MergePreEditHookForTest(root, "entire brain"); err != nil {
		t.Fatalf("merge: %v", err)
