	if strings.TrimSpace(query) == "" {
		return fmt.Errorf("--evidence requires a nonempty query")
	}
	if limit < 1 || limit > 128 {
		return fmt.Errorf("--evidence requires --k between 1 and 128 (candidate sessions)")
