	if err != nil {
		return err
	}
	defer parent.Close()

	temp := ".entire-brain-hook-" + rand.Text()
	staged, err := parent.OpenFile(temp, os.O_WRONLY|os.O_CREATE|os.O_EXCL, perm)
	if err != nil {
