input.content:
// brain-memory — show what Entire Brain actually contributed to each turn.
//
// Brain's value is invisible today. Facts get injected, the agent uses them or
// does not, and nobody sees either. This pane makes the contribution visible,
// and -- more useful -- makes the EMPTY answers visible, because an empty
// result that nobody notices is how a brain quietly stops being consulted.

const PANE = 'brain-memory'
const MAX_TURNS = 12

// Each entry: { turn, tool, query, outcome, detail, note }
let entries = []
let turnNo = 0
let seenAny = false

// --- reading the event, defensively -----------------------------------------
// The event's shape is not something to assume: a wrong field name silently
// records nothing, which looks exactly like "brain was never called".

function toolNameOf(e) {
  const p = e?.props ?? {}
  return String(e?.tool ?? e?.name ?? e?.toolName ?? p.tool ?? p.name ?? p.toolName ?? '')
}

function toolInputOf(e) {
  const p = e?.props ?? {}
  return e?.input ?? e?.args ?? e?.parameters ?? p.input ?? p.args ?? p.parameters ?? {}
}

// Brain is reached two ways, and both count: the MCP tools an agent calls
// directly, and the CLI run through Bash.
function brainCallKind(name, input) {
  if (name.startsWith('mcp__entire-brain__')) {
    return { kind: 'mcp', label: name.slice('mcp__entire-brain__'.length) }
  }
  if (name === 'Bash') {
    const cmd = String(input?.command ?? '')
    const m = cmd.match(/\b(?:entire\s+brain|entire-brain)\s+([a-z-]+)/)
    if (m) return { kind: 'cli', label: m[1] }
  }
  return null
}

function queryOf(input) {
  const raw = input?.query ?? input?.task ?? input?.id ?? input?.symbol ?? input?.command ?? ''
  const s = String(raw).replace(/\s+/g, ' ').trim()
  return s.length > 58 ? s.slice(0, 57) + '…' : s
}

// --- reading the result ------------------------------------------------------
// The point of the pane is the outcome, not that a call happened.

function textOf(result) {
  if (typeof result === 'string') return result
  const content = result?.content ?? result?.props?.content ?? result?.output
  if (typeof content === 'string') return content
  if (Array.isArray(content)) {
    return content.map((c) => (typeof c === 'string' ? c : (c?.text ?? ''))).join('\n')
  }
  try {
    return JSON.stringify(result ?? '')
  } catch {
    return ''
  }
}

// Returns { outcome: 'hit'|'empty'|'error', detail, note }
function summarize(result) {
  const text = textOf(result)
  if (!text) return { outcome: 'empty', detail: 'no output', note: '' }

  let parsed = null
  try {
    parsed = JSON.parse(text)
  } catch {
    /* not JSON; fall through to the text shapes below */
  }

  if (parsed && typeof parsed === 'object') {
    // A blind-spot note is the most valuable thing on this pane: it is brain
    // telling you WHY it had nothing, and it is normally buried in a payload.
    const note = String(parsed.blind_spot ?? '').trim()
    const rows = parsed.results ?? parsed.facts ?? parsed.evidence ?? parsed.anomalies
    if (Array.isArray(rows)) {
      return rows.length > 0
        ? { outcome: 'hit', detail: rows.length + (rows.length === 1 ? ' result' : ' results'), note }
        : { outcome: 'empty', detail: 'no results', note }
    }
    const missing = Array.isArray(parsed.missing) ? parsed.missing.length : 0
    if (missing > 0) return { outcome: 'empty', detail: missing + ' not found', note }
    if (parsed.returned_count !== undefined) {
      const n = Number(parsed.returned_count)
      return n > 0
        ? { outcome: 'hit', detail: n + ' spans', note }
        : { outcome: 'empty', detail: 'no spans', note }
    }
    return { outcome: 'hit', detail: 'ok', note }
  }

  // Text surfaces: brain says "no facts for ..." and then explains itself.
  const low = text.toLowerCase()
  const noteLine = (text.split('\n').find((l) => l.trim().startsWith('note:')) ?? '').trim()
  if (/^no (facts|symbols|impact|results|evidence)\b/m.test(low) || low.includes('not found')) {
    return { outcome: 'empty', detail: 'nothing matched', note: noteLine }
  }
  const lines = text.split('\n').filter((l) => l.trim()).length
  return { outcome: 'hit', detail: lines + (lines === 1 ? ' line' : ' lines'), note: noteLine }
}

// --- drawing ----------------------------------------------------------------

const MARK = { hit: '+', empty: '·', error: 'x' }
const COLOR = { hit: 'green', empty: 'yellow', error: 'red' }

export function register(on) {
  on('session.start', async ($, e, next) => {
    try {
      await $.command.register({
        name: 'brain-memory',
        description: 'What Entire Brain contributed to this session',
      })
    } catch {
      /* a command that cannot register must not break the session */
    }
    return next(e)
  })

  // Group entries by turn, so "what did brain give THIS turn" is answerable.
  on('turn.start', async ($, e, next) => {
    turnNo += 1
    return next(e)
  })

  on('tool.call', async ($, e, next) => {
    let call = null
    try {
      const name = toolNameOf(e)
      const input = toolInputOf(e)
      call = brainCallKind(name, input)
      if (call) call.query = queryOf(input)
    } catch {
      call = null
    }

    // Never let this mod change what the tool does.
    const result = await next(e)
    if (!call) return result

    try {
      const { outcome, detail, note } = summarize(result)
      entries.unshift({
        turn: turnNo,
        tool: call.label,
        kind: call.kind,
        query: call.query,
        outcome,
        detail,
        note,
      })
      if (entries.length > 200) entries.length = 200
      seenAny = true
      $.ui.invalidate('ui.render')
    } catch {
      /* summarising is best effort */
    }
    return result
  })

  on('command.run', { command: 'brain-memory' }, async ($) => {
    await $.ui.open({ id: PANE, title: 'Brain memory', focus: true, closeOnEscape: true })
    return {}
  })

  // A quiet marker beside the spinner, so the pane is discoverable without
  // reading docs: you see brain was consulted, then go look at what it said.
  on('ui.render', { component: 'Spinner' }, async ($, e, next) => {
    if (!seenAny) return next(e)
    const hits = entries.filter((x) => x.outcome === 'hit').length
    const empties = entries.filter((x) => x.outcome === 'empty').length
    const suffix = ' · brain ' + hits + '↑' + (empties ? ' ' + empties + '∅' : '') + '…'
    return next({ ...e, props: { ...e.props, suffix } })
  })

  on('ui.render', { component: 'Pane' }, async ($, e, next) => {
    if (e.requestId !== PANE) return next(e)
    const { Box, Text } = $.ui.resolve(e)

    if (entries.length === 0) {
      return Box({
        flexDirection: 'column',
        children: [
          Text({ bold: true, children: ['Brain memory'] }),
          Text({ children: [' '] }),
          Text({ dimColor: true, children: ['Nothing yet — no brain call has run in this session.'] }),
          Text({
            dimColor: true,
            children: ['If that is unexpected, the agent may not know the brain exists: run `entire brain init-agents`.'],
          }),
        ],
      })
    }

    const hits = entries.filter((x) => x.outcome === 'hit').length
    const empties = entries.filter((x) => x.outcome === 'empty').length

    const rows = []
    let lastTurn = null
    let shownTurns = 0
    for (const x of entries) {
      if (x.turn !== lastTurn) {
        shownTurns += 1
        if (shownTurns > MAX_TURNS) break
        lastTurn = x.turn
        rows.push(
          Text({
            dimColor: true,
            children: [x.turn === turnNo ? '── this turn ' + '─'.repeat(20) : '── turn ' + x.turn + ' ' + '─'.repeat(20)],
          }),
        )
      }
      rows.push(
        Box({
          flexDirection: 'row',
          columnGap: 1,
          children: [
            Text({ color: COLOR[x.outcome], children: [MARK[x.outcome]] }),
            Text({ bold: true, children: [x.tool] }),
            Text({ wrap: 'truncate-end', children: [x.query || '—'] }),
            Text({ dimColor: true, children: ['(' + x.detail + ')'] }),
          ],
        }),
      )
      // The reason an empty answer was empty is the whole point: brain knows,
      // and normally only says so inside a payload nobody reads.
      if (x.note) {
        rows.push(Text({ color: 'yellow', wrap: 'wrap', children: ['    ' + x.note] }))
      }
    }

    return Box({
      flexDirection: 'column',
      children: [
        Box({
          flexDirection: 'row',
          columnGap: 2,
          children: [
            Text({ bold: true, children: ['Brain memory'] }),
            Text({ color: 'green', children: [hits + ' answered'] }),
            Text({ color: empties ? 'yellow' : undefined, dimColor: !empties, children: [empties + ' empty'] }),
          ],
        }),
        Text({ children: [' '] }),
        ...rows,
      ],
    })
  })
}

