// The whole point of the mod. An empty answer must never be counted as an
// answer, and brain's blind_spot note must reach the screen -- it is the only
// place brain says WHY it had nothing, and it is otherwise buried in JSON.
test('an empty brain answer is shown as empty, with the blind-spot note', async ($, on) => {
  const logged = harness(on, { 'mcp__entire-brain__brain_recall': EMPTY_RECALL })

