// --- reading what brain answered ---------------------------------------------
// Grounded in output captured from a running session, not guessed, because the
// two routes nest brain's payload differently and the difference is invisible
// from a unit test:
//
//   Bash: { ref, result: { stdout: '<brain JSON>', stderr, … }, text }
//   MCP:  { ref, result: [ { type: 'text', text: '<brain JSON>' } ], text }
//
// Reading `result.result` as the payload parses the WRAPPER, finds no `results`
// field, and scores every empty answer as a hit -- precisely the failure this
// mod exists to make visible.
//
// The payloads themselves: `recall` returns { facts: [], blind_spot: 'note: …' },
// `search` { results: [], blind_spot }, `get` { results: [], missing: [id] },
// and a hit returns a populated array.

function payloadTextOf(result) {
  if (typeof result === 'string') return result
  const inner = result?.result

  if (typeof inner === 'string') return inner
  // MCP content blocks.
  if (Array.isArray(inner)) {
    return inner.map((c) => (typeof c === 'string' ? c : String(c?.text ?? ''))).join('\n')
  }
  if (inner && typeof inner === 'object') {
    if (typeof inner.stdout === 'string' && inner.stdout.trim()) return inner.stdout
    if (Array.isArray(inner.content)) {
      return inner.content.map((c) => (typeof c === 'string' ? c : String(c?.text ?? ''))).join('\n')
    }
    if (typeof inner.text === 'string' && inner.text.trim()) return inner.text
    // A command that printed only to stderr failed; say so rather than
    // reporting an empty brain for a brain that was never reached.
    if (typeof inner.stderr === 'string' && inner.stderr.trim()) return inner.stderr
  }
  if (typeof result?.text === 'string' && result.text.trim()) return result.text
  return ''
}

// True when the tool itself failed, as distinct from brain answering nothing.
function toolFailed(result) {
  if (result?.isError === true) return true
  const inner = result?.result
  if (inner && typeof inner === 'object' && !Array.isArray(inner)) {
    const hasStdout = typeof inner.stdout === 'string' && inner.stdout.trim() !== ''
    const hasStderr = typeof inner.stderr === 'string' && inner.stderr.trim() !== ''
    if (!hasStdout && hasStderr) return true
    if (inner.interrupted === true) return true
  }
  return false
}

