// it still separates an empty answer from a populated one. The count is a
// lower bound and says so.
const ROW_FIELDS = ['facts', 'results', 'evidence', 'anomalies', 'symbols', 'spans']

function classifyFromText(text) {
  const blind = /"blind_spot"\s*:\s*"((?:[^"\\]|\\.)*)"/.exec(text)
  const note = blind ? clip(blind[1].replace(/\\n/g, ' ').replace(/\\"/g, '"')) : noteLineOf(text)

  for (const field of ROW_FIELDS) {
    const opener = new RegExp('"' + field + '"\\s*:\\s*\\[\\s*(\\]|\\{)')
    const m = opener.exec(text)
    if (!m) continue
    if (m[1] === ']') return { outcome: 'empty', detail: 'nothing matched', note }
    // Each row carries an id, so counting them bounds the answer from below.
    const rows = (text.slice(m.index).match(/"id"\s*:/g) ?? []).length
    const noun = field === 'facts' ? 'fact' : 'result'
    return { outcome: 'hit', detail: rows > 0 ? rows + '+ ' + noun + 's' : 'answered', note }
  }
  return null
}

