for (const field of ROW_FIELDS) {
  const rows = payload[field]
  if (!Array.isArray(rows)) continue
  if (rows.length === 0) return { outcome: 'empty', detail: 'nothing matched', note }
  const noun = field === 'facts' ? 'fact' : 'result'
  // Brain drops tail rows to fit a byte budget and declares it. Reporting
  // only what arrived understates what brain actually had -- the opposite
  // of this pane's job, which is to show the real contribution.
  const total = declaredTotalFor(payload, field)
  const detail = total > rows.length ? rows.length + ' of ' + total + ' ' + noun + 's' : count(rows.length, noun)
  return { outcome: 'hit', detail, note }
}

const ROW_FIELDS = ['facts', 'results', 'evidence', 'anomalies', 'symbols', 'spans']

// Brain fits its reply into a byte budget by dropping tail rows, and records
// what it dropped:
//
//   "response_truncated": true,
//   "response_truncation": { "budget_bytes": 32768,
//     "dropped_from": [ { "path": "results", "returned": 15, "total": 20 } ] }
//
// The JSON stays valid, so the payload parses and nothing looks wrong -- the
// only sign that five rows are missing is this record. Returns 0 when the
// field was not truncated.
function declaredTotalFor(payload, field) {
  const dropped = payload?.response_truncation?.dropped_from
  if (!Array.isArray(dropped)) return 0
  for (const d of dropped) {
    if (d?.path !== field) continue
    const total = Number(d.total)
    return Number.isFinite(total) ? total : 0
  }
  return 0
}

