for (const field of ROW_FIELDS) {
  // `null` and `[]` both mean an empty answer; truncation never reaches
  // either, since both sit at the field's opening.
  const opener = new RegExp('"' + field + '"\\s*:\\s*(null|\\[\\s*\\]|\\[\\s*\\{)')
