  func (i brainIgnore) Ignored(path string) bool {
  	path = filepath.ToSlash(strings.TrimPrefix(path, "./"))
  	if path == ".git" || strings.HasPrefix(path, ".git/") {
  		return true
  	}
  	for _, segment := range []string{"node_modules", "vendor", "dist", "build", "target", ".entire"} {
