  		if path == pattern || strings.Contains(path, "/"+pattern) || strings.HasSuffix(path, pattern) {
  			return true
  		}
  	}
  	for _, pattern := range i.patterns {
  		if brainIgnorePatternMatches(pattern, path) {
  			return true
  		}
  	}
  	return false
