echo "=== entire config / token storage ==="
ls -la ~/.config/entire/ 2>/dev/null | head -10 | sed 's/^/  /'
echo
for f in ~/.config/entire/contexts.json ~/.config/entire/token.json ~/.config/entire/credentials.json; do
  [ -f "$f" ] && echo "  found: $f ($(wc -c <"$f" | tr -d ' ') bytes)"
done
echo
echo "=== is a token stored in a FILE (not keychain)? ==="
python3 -c "
import json,os,glob
for p in glob.glob(os.path.expanduser('~/.config/entire/*.json')):
    try:
        d=json.load(open(p))
    except Exception as e:
        print(f'  {os.path.basename(p)}: unreadable'); continue
    def keys(o,pre=''):
        if isinstance(o,dict):
            for k,v in o.items():
                if any(t in k.lower() for t in ('token','jwt','access','refresh','secret')):
                    print(f'  {os.path.basename(p)}: {pre}{k} = {\"<present>\" if v else \"<empty>\"}')
                keys(v,pre+k+'.')
    keys(d)
" 2>&1 | head -12

