      return Box({
        flexDirection: 'column',
        children: [
          Text({ bold: true, children: ['Brain usage'] }),
          Text({ children: [' '] }),
          Text({ color: 'yellow', wrap: 'wrap', children: ['No brain call in the last ' + u.days + ' days, across ' + (u.data?.files_scanned ?? 0) + ' transcript files.'] }),
          Text({ dimColor: true, wrap: 'wrap', children: ['If that is a surprise, the agent may not know the brain exists: run `entire brain init-agents` in the repo.'] }),
        ],
      })
    }

    const pct = (n) => (t.calls > 0 ? Math.round((n / t.calls) * 100) : 0)
    const header = [
      Text({ bold: true, children: ['Brain usage'] }),
      Text({ dimColor: true, children: ['last ' + u.days + 'd'] }),
      Text({ children: [t.calls + ' calls'] }),
      Text({ color: 'green', children: [t.answered + ' answered'] }),
      t.empty > 0 ? Text({ color: 'yellow', children: [t.empty + ' empty (' + pct(t.empty) + '%)'] }) : Text({ dimColor: true, children: ['0 empty'] }),
    ]
    if (t.failed > 0) header.push(Text({ color: 'red', children: [t.failed + ' failed'] }))

    // One glyph per day: the whole window in a single line, so the trend is
    // readable before any of the detail below it.
    const spark = Box({
      flexDirection: 'row',
      children: days.map((d) => {
        const b = bucket(d.total, max)
        return Text({ color: b < 0 ? undefined : RAMP[b], dimColor: b < 0, children: [barGlyph(d.total, max)] })
      }),
    })

    // Calendar: a column per week, Monday at the top. Quiet days are dim dots so
    // the grid keeps its shape without pretending a zero is a small value.
    const weeks = weeksOf(days)
    const NAMES = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']
    const grid = NAMES.map((name, row) =>
      Box({
        flexDirection: 'row',
        columnGap: 1,
        children: [
          Text({ dimColor: true, children: [name] }),
          ...weeks.map((w) => {
            const d = w[row]
            if (!d) return Text({ children: ['  '] })
            const b = bucket(d.total, max)
            return b < 0
              ? Text({ dimColor: true, children: [EMPTY_CELL] })
              : Text({ color: RAMP[b], children: [CELL] })
          }),
        ],
      }),
    )

    const legend = Box({
      flexDirection: 'row',
      columnGap: 1,
      children: [
        Text({ dimColor: true, children: ['quiet'] }),
        Text({ dimColor: true, children: [EMPTY_CELL] }),
        ...RAMP.map((c) => Text({ color: c, children: [CELL] })),
        Text({ dimColor: true, children: ['busy (max ' + max + '/day)'] }),
      ],
    })

    // Per-day bars for the days that actually had traffic. Days with nothing are
    // already visible in the calendar; repeating them here would be noise.
    const barWidth = Math.max(8, Math.min(32, width - 26))
    const active = days.filter((d) => d.total > 0).reverse().slice(0, 14)
    const bars = active.map((d) => {
      const b = bucket(d.total, max)
      const filled = Math.max(1, Math.round((d.total / Math.max(1, max)) * barWidth))
      return Box({
        flexDirection: 'row',
        columnGap: 1,
        children: [
          Text({ dimColor: true, children: [d.key.slice(5)] }),
          Text({ color: RAMP[b], children: ['█'.repeat(filled)] }),
          Text({ children: [String(d.total)] }),
          d.empty > 0 ? Text({ color: 'yellow', children: ['· ' + d.empty + ' empty'] }) : Text({ children: [''] }),
        ],
      })
    })

    const topVerbs = Object.entries(t.tools).sort((a, b) => b[1] - a[1]).slice(0, 8)
    const verbMax = topVerbs.length > 0 ? topVerbs[0][1] : 0
    const verbRows = topVerbs.map(([verb, n]) =>
      Box({
        flexDirection: 'row',
        columnGap: 1,
        children: [
          Text({ children: [verb.padEnd(12).slice(0, 12)] }),
          Text({ color: RAMP[bucket(n, verbMax)] || 'blue', children: ['█'.repeat(Math.max(1, Math.round((n / Math.max(1, verbMax)) * 18)))] }),
          Text({ dimColor: true, children: [String(n)] }),
        ],
      }),
    )

    const rule = (label) => Text({ dimColor: true, children: [label + ' ' + '─'.repeat(Math.max(1, width - label.length - 1))] })

    return Box({
      flexDirection: 'column',
      children: [
        Box({ flexDirection: 'row', columnGap: 2, children: header }),
        Text({ children: [' '] }),
        spark,
        Text({ dimColor: true, children: [days[0].key + '  →  ' + days[days.length - 1].key + '   ' + t.active + ' of ' + days.length + ' days active'] }),
        Text({ children: [' '] }),
        rule('month'),
        ...grid,
        legend,
        Text({ children: [' '] }),
        rule('busiest days'),
        ...bars,
        Text({ children: [' '] }),
        rule('what it was asked for'),
        ...verbRows,
        Text({ children: [' '] }),
        Text({ dimColor: true, wrap: 'wrap', children: ['route: ' + t.bash + ' via CLI, ' + t.mcp + ' via MCP · ' + (u.data?.files_scanned ?? 0) + ' transcript files scanned'] }),
      ],
    })
  })
'''

